var n=`0856-poori`;var t=`world-0856`;var s=`IN`;var a=`south-asia`;var o=8;var r=49;var h={en:`Poori`,ua:`Пурі`};var l={en:`Poori is a India dish made with whole wheat flour. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Пурі, страва кухні країни Індія. Основні складники: цільнозернове пшеничне борошно. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 15 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 15 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:15,i:[[`whole-wheat-flour`,360,`g`],[`water`,195,`ml`],[`table-salt`,5,`g`],[`canola-oil`,22,`ml`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 20 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 20 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:20,i:[[`canola-oil`,750,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`ghee`,20,`g`]]}];var g={slug:n,id:t,country:`IN`,region:a,servings:8,minutes:49,title:h,text:l,steps:d};export{s as country,g as default,t as id,r as minutes,a as region,o as servings,n as slug,d as steps,l as text,h as title};